import {apiRequest} from './api-client.js';
/** Storage controls fail closed. Uploads use a scoped gateway, never reusable S3 presigned requests. */
export function mountR2Studio(root,{selectedTitle,release,toast,onPublished,onCleanup}){
 const section=document.createElement('section');section.className='state-panel';section.innerHTML='<h3>3. Upload movie or episode · Private R2</h3><p>Encode the original locally with tools/encode_hls.py, then choose its HLS output folder. Originals remain on your computer. All uploaded renditions share an 8 GB reservation cap.</p><button class="button button-secondary" id="r2Usage">Check usage & renewal dates</button><pre id="r2Limits" class="muted"></pre><label>Encoded HLS folder<input id="r2Files" type="file" webkitdirectory multiple></label><label><input id="r2Resume" type="checkbox"> Resume an existing reservation</label><button class="button button-primary" id="r2Upload">Upload HLS bundle</button><label><input id="r2Rights" type="checkbox"> I reviewed distribution rights.</label><label><input id="r2Captions" type="checkbox"> I reviewed captions and accessibility.</label><button class="button button-secondary" id="r2Publish" disabled>Publish R2 video</button><p id="r2Status" role="status">No upload in progress.</p>';root.append(section);
 const $=id=>section.querySelector('#'+id);let reservation=null,title=null,closed=false,controller=null;onCleanup?.(()=>{closed=true;controller?.abort();});
 root.addEventListener('studio:selection',()=>{$('r2Rights').checked=$('r2Captions').checked=false;try{$('r2Publish').disabled=!reservation||selectedTitle()!==title;}catch{$('r2Publish').disabled=true;}});
 $('r2Usage').onclick=async()=>{try{const usage=await apiRequest('/api/admin/storage/limits');$('r2Limits').textContent=JSON.stringify(usage,null,2);}catch(e){$('r2Limits').textContent=e.message;}};
 $('r2Upload').onclick=async()=>{const button=$('r2Upload');button.disabled=true;try{
  title=selectedTitle();const files=[...$('r2Files').files].filter(f=>/^[A-Za-z0-9_-]+\.(m3u8|ts|m4s|mp4)$/.test(f.name));
  if(!files.some(f=>f.name==='master.m3u8')||new Set(files.map(f=>f.name)).size!==files.length)throw new Error('Choose one flat HLS bundle with master.m3u8 and unique filenames.');
  const bytes=files.reduce((n,f)=>n+f.size,0);if(bytes>8e9||files.length>20000||files.some(f=>!f.size||f.size>16777216))throw new Error('Bundle exceeds the storage, file-count or 16 MiB segment limit.');
  reservation=$('r2Resume').checked?await apiRequest(`/api/admin/r2/${title}/reservation`):await apiRequest(`/api/admin/r2/${title}/reserve`,{method:'POST',body:JSON.stringify({bytes,files:files.length})});
  const base=new URL(reservation.uploadBase);if(base.protocol!=='https:'||base.username||base.password)throw new Error('Invalid private media gateway');controller=new AbortController();let sent=0;
  for(const file of files){if(closed)return;$('r2Status').textContent=`Uploading ${++sent}/${files.length} · ${file.name}`;const response=await fetch(base.href+'/'+file.name,{method:'PUT',body:file,credentials:'omit',signal:controller.signal});if(!response.ok)throw new Error('Upload stopped by the media gateway. Check limits, then resume the same reservation.');}
  if(!closed){$('r2Status').textContent='Bundle transferred. Review rights and captions, then publish.';$('r2Publish').disabled=false;}
 }catch(e){if(!closed)$('r2Status').textContent=e.message;}finally{button.disabled=false;}};
 $('r2Publish').onclick=async()=>{try{if(selectedTitle()!==title)throw new Error('Select the draft used for this upload before publishing.');const plan=release();if(!$('r2Rights').checked||!$('r2Captions').checked)throw new Error('Complete both publishing reviews.');await apiRequest(`/api/admin/r2/${title}/publish`,{method:'POST',body:JSON.stringify({bundleId:reservation.bundleId,rightsReviewed:true,captionsReviewed:true,...plan})});$('r2Status').textContent=plan.releaseAt?'Scheduled for '+new Date(plan.releaseAt).toLocaleString()+'. It stays private until release.':'Published. Signed-in members can stream the real video.';toast(plan.releaseAt?'R2 release scheduled':'R2 video published');$('r2Publish').disabled=true;await onPublished?.();}catch(e){$('r2Status').textContent=e.message;}};
}
